const f=document.getElementById('statusForm'),i=document.getElementById('statusInput'),a=document.getElementById('statusAnswer');f.addEventListener('submit',e=>{e.preventDefault();const v=i.value.trim();if(!v){a.textContent='Введите номер телефона или заказа.';return}a.innerHTML='Чтобы уточнить статус сейчас, <a style="color:#0b5cff;font-weight:700" target="_blank" rel="noopener" href="https://wa.me/79502004454?text='+encodeURIComponent('Здравствуйте, PRO.Apple! Подскажите статус ремонта/заказа: '+v)+'">напишите нам в WhatsApp →</a>'});